    # and output it line by line.
    tour = []
    seen = set()

    def tour_generator(start_node):
        stack = [start_node]
        while stack:
            node = stack.pop()
            if node not in seen:
                tour.append(node+1)
                seen.add(node)
                for neighbor in reversed(graph[node]):
                    if neighbor not in seen:
                        seen.add(neighbor)
                        stack.append(neighbor)
        return tour

    tour = tour_generator(0)
    return tour

def count_ways(tour):
    numbers = [0] * n
    # Select the middle number on the Euler tour
    middle = tour[len(tour)//2]
    for i in range(n):
        numbers[i] = i % 3
    # Swap the middle numbers and select independent Edmonds tours from the new middle numbers on the edge
    return count_edmonds_tours(numbers)

def count_edmonds_tours(numbers):
    choices, used, pot, size = [], set(), set(), len(numbers)
    for _ in range(2**(size)):
