from typing import List, Tuple

def find_subset_with_divisible_sum(N: int, numbers: List[int]) -> Tuple[int, List[int]]:

    # Check if the sum of the entire set is divisible by N
    set_sum = sum(numbers)
    if set_sum % N != 0:
        return -1

    # Precompute the remainders of each number when divided by N
    remainders = {number % N for number in numbers}

    # Iterate through all possible subsets
    for subset_size in range(1, len(numbers) + 1):
        for subset_indices in range(1 << len(numbers)):
            subset_sum = set()
            for index in range(len(numbers)):
                if (subset_indices >> index) & 1:
                    subset_sum.add(numbers[index] % N)
            if subset_sum == remainders:
                return subset_size, sorted([index for index in range(len(numbers)) if (1 << index) & subset_indices])

# Read input
