from collections import deque

def find_smallest_string(S):
    freq = [0] * 26
    for c in S:
        freq[ord(c) - ord('a')] += 1

    swaps = 0
    for i in range(26):
        swaps += 1 if freq[i] > 0 else 0

    total_cost = swaps * 2 + (len(S) - swaps)

    def replace_with_kth_char(i):
        nonlocal total_cost
        if total_cost <= 0:
            return 0, 0
        if freq[i] == 0:
            return 0, 0

        if freq[i] > 1:
            cost = total_cost // freq[i] * i * 2
            return cost, i

        if freq[i] == 2:
            cost = total_cost * 2
            return cost, 2

        return 2, i

    def perform_swap():
        nonlocal total_cost
        if total_cost < 0:
            return 0

        min_cost = total_cost
        start_char, min_char = 0, 26

        for i in range(26):
            min_cost = min(min_cost, total_cost - i)
            if freq[i] > 1:
                last_index = i - 1
                last_index += total_cost // freq[last_index] * freq[last_index] - 1

                diff = 1 + sum(front[0] for front in forward_span if i in front)
                actual_cost = diff // 2 * i * 2 + diff % 2 * i + freq[i]
                if total_cost - actual_cost < min_cost:
                    cost, result_char = replace_with_kth_char(last_index)
                    total_cost = min_cost
                    min_char = result_char
                    min_cost = cost
                    break

        for i in range(26):
            if i == min_char:
                continue

            next_index = i + 1
            if next_index >= 26:
                continue

            if freq[i] > 0 and freq[next_index] > 0:
                actual_cost = (2 * freq[i] - 2 * freq[next_index]) // 2
                min_cost = min(min_cost, total_cost - actual_cost)
                if min_cost == total_cost - 2 * freq[next_index]:
                    result_char = next_index
                    break

        return total_cost - min_cost, min_char

    kth_char = find_smallest_kth_char(S)

    while total_cost > kth_char:
        cost, char = perform_swap()
        total_cost -= cost 

    min_cost = total_cost
    freq[char] -= 1
    freq[S[0]] -= 1

    for i in range(1, len(S)):
        if freq[S[i]] > 0:
            suit = replace_with_kth_char(i)
            min_cost = min(min_cost, suit[0])
            freq[S[i]] -= 1

    freq[S[-1]] -= 1

    total_cost -= min_cost

    ans = deque()

    while total_cost > 0:
        nonlocal min_cost
        total_cost, char = replace_with_kth_char(ans[-1])
        ans.pop()

    while total_cost < 0:
        nonlocal min_cost
        total_cost, char = perform_swap()
        ans.append(char)

    return ''.join(ans.flip())

def find_smallest_kth_char(S):
    total_cost = 0
    count = []
    for i in range(26):
        freq = S.count(chr(i + ord('a')))
        div = freq // 2

        for k in range(26):
            lowest = freq + total_cost // div + (1 if freq % div > 1 else 0) // k
            if div * k < lowest < total_cost or div * k == total_cost:
                count.append((k, lowest))

        total_cost += freq * 2

    length = len(S)
    div = length // 2
    if length % 2 == 1:
        start_idx = length // 2 * 2 - 2
    else:
        start_idx = length // 2 * 2 - 1

    min_div_cost = float('inf')
    for k, comp in count:
        if freq % div > (k - 1):
            if comp <= total_cost:
                cost = 2
            else:
                cost = comp - total_cost
        else:
            diff = freq % div - k + 1
            if diff % 2 != 0 and k % 2 != 0:
                diff = 1 + diff
            cost = 2 * freq // div + diff // (1 if k % 2 == 0 and diff >= k - 1 else 0)

        if diff <= 2 * len(count) and diff >= k - 1:
            min_div_cost = min(min_div_cost, cost)

