import heapq
from collections import defaultdict

def build_tree():
    n = int(input())
    edges = []
    for _ in range(n-1):
        x, y, w, p = map(int, input().split())
        edges.append((w, p, x, y))
    return n, edges

def find_cycle(heap):
    parents, children = defaultdict(list), defaultdict(set)
    for w, p, x, y in heap:
        if parents[y] == x:
            cycle = set(map(lambda z: z[1], heap)) - {y}
            if len(cycle) >= 3 and w > p:
                return cycle
        parents[x] = y
        children[y].add(cycle)
    return None

def process(heap):
    ans = []
    for w, p, x, y in heap:
        if parents[x] == y:
            cycle = set(map(lambda z: z[1], heap)) - {y}
            ans.extend(map(lambda z: (z[1], w, p), cycle))
        else:
            ans.append((w, p, x, y))
    return ans

def restore_tree(heap):
    parents, cycle = {}, set()
    for w, p, x, y in heap:
        parents[y] = x
        if x in cycle:
            for z in cycle:
                parents[z] = y
                cycle.add(y)
    p = parents[1]
    for w, p, x, y in heap:
        if x == y:
            parents[y] = parents[y] - {p}
    return parents

def find_min_cost_tree(n, edges):
    heap = []
    for w, p, x, y in edges:
        heapq.heappush(heap, (w, p, x, y))
    cycle = find_cycle(heap)
    if cycle:
        return -1
    parents, children = {}, defaultdict(set)
    while heap:
        w, p, x, y = heapq.heappop(heap)
        if parents[x] == y:
            cycle = set(map(lambda z: z[1], heap)) - {y}
            if len(cycle) < 3 or w > p:
                return find_min_cost_tree(len(heap), heap)
        children[y] |= {cycle}
        parents[x] = y
    return restore_tree(heap)

def main():
    n, edges = build_tree()
    result = find_min_cost_tree(n, edges) or -1
    if len(result):
        print(f"{n}")
        for w, p, x, y in result:
            print(f"1 {x} {w} {p}")

if __name__ == "__main__":
    main()
