from math import gcd

def is_weakly_connected(edges):
    """Check if the graph is weakly connected."""
    visited = [False] * (max(edges) + 1)
    for i, _ in sorted(edges, key=lambda x: x[1]):
        if visited[i]:
            return False
        visited[i] = True
    return all(visited)

def find_gcd_if_exist(a, b):
    """Return the greatest common divisor of two numbers if one exists, otherwise 0."""
    if a == 0 or b == 0:
        return 0
    return gcd(a, b)

def is_valid_assignment(edges):
    """Check if there exists an assignment satisfying the conditions."""
    edge_sets = [[] for _ in range(len(edges) + 1)]
    for u, v in edges:
        edge_sets[u].append(v)
        if u < v:
            if any((find_gcd_if_exist(a_i, find_gcd_if_exist(edges[u][0], v)) != 0 for a_i in edge_sets[v])):
                return False
    return True

