def get_winning_ways(n, alphabet_size):
    dp = [0] * (n + 1)
    for i in range(n, -1, -1):
        for length in range(1, alphabet_size + 1):
            if 0 < i + length - 1 <= n:
                dp[i] = (dp[i] + dp[i + length - 1]) % MOD
            if i > 0:
                dp[i] = (dp[i] + alphabet_size - 1 - 1) % MOD

