def dfs(graph, visited, next, index):
    for node, edge_sum in graph[node]:
        if not visited[node][next]:
            visited[node][next], visited[node][node] | edge_sum = node, edge_sum | visited[node][next]
            dfs(graph, visited, next, edge_sum)

def solve(n, edges):
    connected = defaultdict(set)
    for a, b in edges:
        connected[a].add(b)
        connected[b].add(a)
    visited = [[set(), set(), set()] for _ in range(n + 1)]
    dfs(connected, visited, 1, 0)
    sum_visited = {t: len(visited[i]) for i, t in enumerate(visited) if all(t[i])}
    min_val = min(sum_visited.values())
    diff = sum_visited[min_val]
    return (1 << n) - n * diff - diff * diff + 2 * diff - 2 * diff * min_val + 2 * diff * diff * (min_val - 1)

