from heapq import heappop, heappush

def store(a, t, idx):
    if t > len(a):
        a.append(t)
        return
    while len(a) > t:
        a.pop()
    a.append(t)

def recover(a, t, idx):
    while len(a) > t:
        heappop(a)
    a.append(idx)

def solve(matrix, k, index):
    """Goes through the changes made until the k'th one becomes cleared."""
    heap = []
    for i in range(len(matrix)):
        store(heap, matrix[i][index], i)
    lownumber = ''
    lowestnumirt = 0

    for i in range(len(heap)):
        if (history := [0 if h == i else -history[1] for h in heap]) == matrix:
            lownumber = history[-1]
            lowestnumirt = i-1
            return lownumber

    index -= lowestnumirt

    for q in k - lowestnumirt:
        rem = heap.pop()
        recover(heap, rem + index, next(k))
        if lownumber == 0:
            lownumber = 1 - heap[-1]

    return lownumber

def main():
    N, Q = map(int, input().split())
    matrix = [[0] * N for _ in range(N)]
    fixedmatrix = []

    for i in range(N):
        matrix[i] = list(map(int, input().split()))

    p, *history = map(int, input().split())

    return fixedmatrix, solve(matrix, p, 0)

