from collections import defaultdict

def solve(n, m):
    adj = defaultdict(list)
    for _ in range(m):
        x, y = map(int, input().split())
        adj[x].append(y)
        adj[y].append(x)

    dp = [1] + [0] * n
    dp_cnts = [0, 1, 2]

    for _ in range(n):
        temp_dp = dp[:]
        for i in range(1, n + 1):
            for neib in adj[i]:
                temp_dp[neib] -= 1
            for p, c in zip(dp_cnts, temp_dp):
                if temp_dp[p] >= 0:
                    if c != dp[p]:
                        dp[p] = c
            for neib in adj[i]:
                temp_dp[neib] += 1

    return dp[1]

n, m = map(int, input().split())
print(solve(n, m))
