def fibonacci_string(n):
    if n == 0:
        return "0"
    elif n == 1:
        return "1"
    else:
        a, b = "0", "1"
        for _ in range(2, n + 1):
            a, b = b, a + b + b
        return b

def lexicographical_suffixes(length):
    fib = fibonacci_string(length)
    return [fib[i:] for i in range(length)]

def main(n, k, m):
    fib = fibonacci_string(n)
    suffixes = lexicographical_suffixes(n)
    if (k - 1) // m >= len(suffixes):
        return suffixes[(k - 1) // m - 1]
    else:
        result = []
        target_index = (k - 1) // m
        for i in range(m):
            result.append(fib[target_index - 1 - i:i + 1])
        return ''.join(result)

# Read input
